    ms=[(r,c,a[r][c]) for r in range(H) for c in range(W) if a[r][c]!=bgv]
    # multi-source BFS on "diagonal movement": each step move diagonally; track parity of steps
    out=[[bgv]*W for _ in range(H)]
    dist=[[None]*W for _ in range(H)]
    q=deque()
    for (mr,mc,v) in ms:
        for sgn_r,sgn_c in [(1,1),(1,-1),(-1,1),(-1,-1)]:
            q.append((mr,mc,0,v))  # start here
            dist[mr][mc]=0
    while q:
        r,c,t,_=q.popleft()
        for sgn_r,sgn_c in [(1,1),(1,-1),(-1,1),(-1,-1)]:
            nr,nc=r+sgn_r,c+sgn_c
            if 0<=nr<H and 0<=nc<W:
                nd=t+1
                if dist[nr][nc] is None or nd<dist[nr][nc]:
                    dist[nr][nc]=nd; q.append((nr,nc,nd,a[(r,c)][a.index((r,c))[2]] if False else 0))
    return dist
